beforeSaveCustomScript:
// ============================================
// Format License Key (4-character groups)
// ============================================

if (license != '' && license != null) {
    // Remove existing dashes and spaces
    $cleaned = string\replace(string\replace(license, '-', ''), ' ', '');
    $length = string\length($cleaned);
    
    if ($length > 4) {
        $formatted = '';
        $i = 0;
        while ($i < $length) {
            $chunk = string\substring($cleaned, $i, 4);
            $formatted = string\concatenate($formatted, $chunk);
            $i = $i + 4;
            if ($i < $length) {
                $formatted = string\concatenate($formatted, '-');
            }
        }
        license = $formatted;
    }
}
